with flattened as (select c.id, c.customer_id, c.created_at, c.coupon_codes, item.product_id, item.price, item.promo from carts c lateral view explode(c.items) e as item), exploded as (select product_id, element from flattened lateral view outer explode(coupon_codes) li as element), enriched as (select product_id, element, cume_dist() over (order by product_id nulls last) as product_id_cume_dist, cume_dist() over w_recent as product_id_cume_dist_2, dense_rank() over (partition by element order by product_id desc nulls first) as product_id_dense_rank from exploded where element = 'SPRING10' window w_recent as (partition by element order by product_id desc)), scored as (select product_id_cume_dist, product_id_cume_dist_2, product_id_dense_rank, rank() over (order by product_id_cume_dist_2 nulls last) as product_id_cume_dist_2_rank from enriched), grouped as (select case when product_id_dense_rank >= 7 then 'LARGE' else 'SMALL' end as product_id_dense_rank_tier, case when product_id_cume_dist_2_rank >= 7 then 'LARGE' else 'SMALL' end as product_id_cume_dist_2_rank_tier, round(avg(product_id_dense_rank), 2) as avg_product_id_dense_rank, count(*) as event_count, count(*) as event_count_2 from scored group by case when product_id_dense_rank >= 7 then 'LARGE' else 'SMALL' end, case when product_id_cume_dist_2_rank >= 7 then 'LARGE' else 'SMALL' end) select product_id_dense_rank_tier, product_id_cume_dist_2_rank_tier, avg_product_id_dense_rank, event_count, event_count_2 from grouped order by product_id_cume_dist_2_rank_tier desc, event_count_2
